function N({registerIndicator:f,sourceValues:h,nulls:d}){f({id:"oa-sinema",name:"Sine-weighted Moving Average (SINEMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"sinema",type:"line",title:"SINEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,r){const y=Math.max(1,Math.floor(Number(r.period)||10)),a=h(o,r.source??"close"),c=new Array(o.length).fill(NaN);let s=0,n=[];for(let t=0;t<o.length;t++){const i=Math.min(t+1,y);if(i!==s){n=new Array(i);for(let e=0;e<i;e++)n[e]=Math.sin(Math.PI*(e+1)/i);s=i}let u=0,l=0;for(let e=0;e<i;e++){const p=a[t-e];Number.isFinite(p)&&(u+=p*n[e],l+=n[e])}const m=l!==0?u/l:NaN;c[t]=Number.isFinite(m)?m:a[t]}return{sinema:d(c)}}})}export{N as default};
